function o(t){return String(t).padStart(2,"0")}function s(t=new Date){return`${t.getFullYear()}-${o(t.getMonth()+1)}-${o(t.getDate())}`}function u(t){const[e,a,n]=t.split("-").map(Number);return new Date(e,a-1,n)}function c(t,e){const a=u(t);return a.setDate(a.getDate()+e),s(a)}function f(t,e=new Date){const a=s(e);if(t==="week"){const r=new Date(e);return r.setDate(r.getDate()-6),{start:s(r),end:a}}if(t==="all")return{start:"1970-01-01",end:a};const n=new Date(e.getFullYear(),e.getMonth(),1);return{start:s(n),end:a}}function i(t){return u(t).getTime()}function D(t){const e=u(t);return e.setDate(e.getDate()+1),e.getTime()}function g(t){const e=Math.max(0,Math.floor(t/1e3)),a=Math.floor(e/3600),n=Math.floor(e%3600/60),r=e%60;return a>=1?`${a}小时 ${o(n)}分`:n>=10?`${n}分`:n>=1?`${n}分${o(r)}秒`:`${r}秒`}function l(t,e,a){return Math.min(a,Math.max(e,t))}export{c as a,l as c,D as e,g as f,u as p,f as r,i as s,s as t};
